scenario = "helpers for the checks below"
def covers_every_item_once():
    """For many (total, per_page) pairs, put the pages' slices end to end and check that they rebuild the list exactly."""
    for total in range(0, 31):
        for per_page in range(1, 8):
            items = list(range(total))
            total_pages = page_window(total, 1, per_page)["total_pages"]
            rebuilt = []
            for page in range(1, total_pages + 1):
                window = page_window(total, page, per_page)
                if window["page"] != page:
                    raise AssertionError(f"total={total}, per_page={per_page}: page {page} is a real page, but page_window served page {window['page']}")
                rebuilt += items[window["start"]:window["end"]]
            if rebuilt != items:
                raise AssertionError(f"total={total}, per_page={per_page}: the pages put together are {rebuilt}, not {items}")
    return True
def rejects_per_page(per_page):
    """True if page_window raises ValueError for this page size; otherwise say what happened."""
    try:
        result = page_window(95, 1, per_page)
    except ValueError:
        return True
    except Exception as error:
        raise AssertionError(f"per_page={per_page} raised {type(error).__name__}, expected ValueError") from None
    raise AssertionError(f"per_page={per_page} was accepted (it returned {result!r}), expected ValueError")
